3	/**
4	 * Static, non-interactive label (e.g. a listener's topic). For a toggleable
5	 * version use <Chip>.
6	 */
7	export function Tag({ children }: { children: React.ReactNode }) {
8	  return (
9	    <span className="inline-flex items-center rounded-pill border border-border bg-surface-sunk px-3 py-1 text-sm font-semibold text-ink-soft">
10	      {children}
11	    </span>
12	  );
13	}
